mapper.select:
SELECT d.*, sd.dept_name AS dept_name
FROM phm_device d
LEFT JOIN sys_dept sd ON sd.dept_id = d.dept_id
WHERE 1 = 1

    AND d.id = #{deviceId}


    AND d.device_code = #{deviceCode}


    AND (d.device_code LIKE CONCAT('%', #{keyword}, '%')
         OR d.device_name LIKE CONCAT('%', #{keyword}, '%'))


    AND d.org_name LIKE CONCAT('%', #{orgName}, '%')


    AND d.status = #{status}

${params.dataScope}
ORDER BY d.device_code ASC
